from collections import Counter

class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        m = len(s1)
        if m > len(s2):
            return False
        need = Counter(s1)
        window = Counter(s2[:m])
        if window == need:
            return True
        for right in range(m, len(s2)):
            left_char = s2[right - m]
            window[left_char] -= 1
            if window[left_char] == 0:
                del window[left_char]
            window[s2[right]] += 1
            if window == need:
                return True
        return False

